mapper.select:
SELECT id, permission_code, permission_name, permission_type, path, status, create_at
FROM sys_permission
WHERE id = #{id}

SELECT id, permission_code, permission_name, permission_type, path, status, create_at
FROM sys_permission
WHERE permission_code = #{permissionCode}

SELECT id, permission_code, permission_name, permission_type, path, status, create_at FROM sys_permission
(permission_code LIKE CONCAT('%', #{keyword}, '%') OR permission_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
